import std.io
import std.collections

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let m = collections.mapOf([1, 2, 3], [10, 20, 30])
    m.put(4, 40)
    match m.get(2) {
        Some(v) => { io.println("two:${v}") }
        None => { io.println("two:none") }
    }
    match m.remove(1) {
        Some(v) => { io.println("rm:${v}") }
        None => { io.println("rm:none") }
    }
    let ks = m.keys()
    for k in ks {
        match m.get(k) {
            Some(x) => { io.println("k:${k}=${x}") }
            None => { io.println("miss") }
        }
    }
    io.println("size:${m.size()}")
    let n = collections.mapOf(["a", "b"], [1, 2])
    n.put("c", 3)
    match n.get("b") {
        Some(v) => { io.println("b:${v}") }
        None => { io.println("b:none") }
    }
    io.println("nsize:${n.size()}")
    return Ok(())
}
